package com.example.starter.observation;

import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 坐标基准转换规则发布请求。版本号由调用方指定且全局唯一，发布后不可变、不可删除。
 *
 * @param ruleVersion      规则版本号，正整数，全局唯一
 * @param targetFrame      目标坐标基准标识
 * @param offsetX          X 方向偏移量（目标基准长度单位）
 * @param offsetY          Y 方向偏移量（目标基准长度单位）
 * @param effectiveFromUtc 生效起点（UTC，含）
 * @param effectiveToUtc   生效终点（UTC，不含）；为 null 表示自起点起长期有效；非 null 时必须严格晚于起点
 */
public record PublishRuleRequest(
        @NotNull @Min(1) Integer ruleVersion,
        @NotBlank @Size(max = 64) String targetFrame,
        @NotNull @Digits(integer = 9, fraction = 9) BigDecimal offsetX,
        @NotNull @Digits(integer = 9, fraction = 9) BigDecimal offsetY,
        @NotNull Instant effectiveFromUtc,
        Instant effectiveToUtc) {
}

package com.example.starter.observation;

import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 坐标观测写入请求：观测携带原基准、原坐标与观测时刻（UTC）。
 *
 * <p>服务端按观测时刻选择生效区间左闭右开的唯一规则；同一 requestId 重放返回首次结果，
 * 修改原基准或坐标（以及观测时刻）一律 409。
 *
 * @param requestId     全局唯一请求标识（幂等去重键）
 * @param observationId 坐标观测业务唯一标识
 * @param sourceFrame   原坐标基准标识
 * @param originalX     原坐标 X（原基准长度单位）
 * @param originalY     原坐标 Y（原基准长度单位）
 * @param observedAtUtc 观测时刻（UTC）
 */
public record CoordinateObservationRequest(
        @NotBlank @Size(max = 128) String requestId,
        @NotBlank @Size(max = 64) String observationId,
        @NotBlank @Size(max = 64) String sourceFrame,
        @NotNull @Digits(integer = 9, fraction = 9) BigDecimal originalX,
        @NotNull @Digits(integer = 9, fraction = 9) BigDecimal originalY,
        @NotNull Instant observedAtUtc) {
}

package com.example.starter.observation;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 坐标基准转换规则响应：返回规则版本、目标基准、X/Y 偏移量与 UTC 生效区间（左闭右开）。
 *
 * @param ruleVersion      规则版本号
 * @param targetFrame      目标坐标基准标识
 * @param offsetX          X 方向偏移量（目标基准长度单位，九位小数规范化）
 * @param offsetY          Y 方向偏移量（目标基准长度单位，九位小数规范化）
 * @param effectiveFromUtc 生效起点（UTC，含）
 * @param effectiveToUtc   生效终点（UTC，不含）；null 表示长期有效
 */
public record RuleResponse(
        int ruleVersion,
        String targetFrame,
        BigDecimal offsetX,
        BigDecimal offsetY,
        Instant effectiveFromUtc,
        Instant effectiveToUtc) {

    /**
     * 由持久化规则构造响应。
     */
    public static RuleResponse of(CoordinateRule rule) {
        return new RuleResponse(rule.ruleVersion(), rule.targetFrame(),
                rule.offsetX(), rule.offsetY(),
                rule.effectiveFromUtc(), rule.effectiveToUtc());
    }
}

