                                + "target_frame, target_x, target_y, rule_version, review_status, auto_merged "
                                + "FROM coordinate_observation WHERE observation_id = ?",
                        OBSERVATION_MAPPER, observationId)
                .stream().findFirst();
    }

    /**
     * 按请求标识查询坐标观测（幂等重放路径）；不存在时返回空。
