                () -> callIngest(obs("req-p2", "obs-p2", "5", "20", IN_OVERLAP)),
                () -> callIngest(obs("req-p3", "obs-p3", "5", "20", IN_OVERLAP)));
        List<Outcome> results = runConcurrently(tasks);

        // 发布必定成功；观测只有两种串行化结局：V2 提交前拿锁 → 201 且只能按 V1 转换；
