    @Test
    void concurrentDistinctObservationsAllCommitWithFrozenRule() throws Exception {
        coordinateFrameService.publishRule(rule(1, "FRAME-1", "0", "0", V1_FROM));

        List<Callable<Outcome>> tasks = new ArrayList<>();
        for (int i = 1; i <= 4; i++) {
            final int index = i;
